const STATE = require('STATE')
const statedb = STATE(__filename)
const { get } = statedb(fallback_module)

const graph_explorer = require('graph-explorer')
const net_helper = require('net_helper')

module.exports = menu_sidebar

async function menu_sidebar (opts, invite) {
  const { sid } = opts
  const { id, sdb } = await get(sid)
  const db_request_causes = new Map()
  const early_db_responses = new Map()

  const { io, _ } = net_helper(id)
  io.on = {
    up: onmessage,
    graph_explorer: graph_explorer_protocol
  }
  if (invite) io.accept(invite)

  const el = document.createElement('div')
  el.className = 'sidebar-container'

  const subs = await sdb.watch(onbatch)

  if (subs && subs.length > 0) {
    const explorer_el = await graph_explorer({ sid: subs[0].sid }, io.invite('graph_explorer', { storage: id }))
    el.appendChild(explorer_el)
  }

  return el

  function onmessage (msg) {
    if (_.graph_explorer) {
      const refs = refs_for_graph_explorer(msg)
      if (refs) _.graph_explorer(msg.type, refs, msg.data)
    }
  }

  function graph_explorer_protocol (msg) {
    const refs = msg.head ? { cause: msg.head } : msg.refs || {}
    const head = _.up(msg.type, refs, msg.data)
    if (msg.type.startsWith('db_')) {
      db_request_causes.set(JSON.stringify(head), msg.head)
      flush_early_db_response(head)
    }
  }

  function onbatch (batch) { }

  function refs_for_graph_explorer (msg) {
    const refs = msg.refs ? { ...msg.refs } : {}
    if (msg.type === 'db_response' && refs.cause) {
      const response_key = JSON.stringify(refs.cause)
      const original_head = db_request_causes.get(response_key)
      if (original_head) {
        db_request_causes.delete(response_key)
        refs.cause = original_head
      } else {
        early_db_responses.set(response_key, msg)
        return null
      }
      return refs
    }
    if (!refs.cause && msg.head) refs.cause = msg.head
    return refs
  }

  function flush_early_db_response (head) {
    const response_key = JSON.stringify(head)
    const msg = early_db_responses.get(response_key)
    if (!msg) return
    early_db_responses.delete(response_key)
    onmessage(msg)
  }
}

function fallback_module () {
  const _ = {
    'graph-explorer': { $: '' },
    net_helper: { $: '' }
  }

  return { _, api: fallback_instance }

  function fallback_instance () {
    const _ = {
      'graph-explorer': {
        $: '',
        0: '',
        mapping: {
          style: 'style',
          runtime: 'runtime',
          mode: 'mode',
          flags: 'flags',
          keybinds: 'keybinds',
          undo: 'undo'
        }
      },
      net_helper: { 0: '' }
    }

    const drive = {
      'style/': { 'style.css': { $ref: 'style.css' } },
      'entries/': { 'entries.json': { $ref: '../news/entries.json' } },
      'runtime/': {
        'node_height.json': { raw: '32' },
        'vertical_scroll_value.json': { raw: '0' },
        'horizontal_scroll_value.json': { raw: '0' },
        'selected_instance_paths.json': { raw: '[]' },
        'confirmed_selected.json': { raw: '[]' },
        'instance_states.json': {
          raw: JSON.stringify({
            '|/': { expanded_subs: true },
            '|/my-blogs1': { expanded_subs: true },
            '|/my-blogs2': { expanded_subs: true },
            '|/discover': { expanded_subs: true }
          })
        },
        'search_entry_states.json': { raw: '{}' },
        'last_clicked_node.json': { raw: 'null' },
        'view_order_tracking.json': { raw: '{}' }
      },
      'mode/': {
        'current_mode.json': { raw: '"menubar"' },
        'previous_mode.json': { raw: '"menubar"' },
        'search_query.json': { raw: '""' },
        'multi_select_enabled.json': { raw: 'false' },
        'select_between_enabled.json': { raw: 'false' }
      },
      'flags/': {
        'hubs.json': { raw: '"default"' },
        'selection.json': { raw: 'true' },
        'recursive_collapse.json': { raw: 'true' }
      },
      'keybinds/': {
        'navigation.json': {
          raw: JSON.stringify({
            ArrowUp: 'navigate_up_current_node',
            ArrowDown: 'navigate_down_current_node',
            'Control+ArrowDown': 'toggle_subs_for_current_node',
            'Control+ArrowUp': 'toggle_hubs_for_current_node',
            'Alt+s': 'multiselect_current_node',
            'Alt+b': 'select_between_current_node',
            'Control+m': 'toggle_search_mode',
            'Alt+j': 'jump_to_next_duplicate'
          })
        }
      },
      'undo/': { 'stack.json': { raw: '[]' } }
    }

    return { _, drive }
  }
}
